import{z as d,x as p,o as r,c as E,q as s,j as n,D as o,d as a,s as l,S as m,b as i}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"initramfs 与 pivot_root","description":"","frontmatter":{"title":"initramfs 与 pivot_root","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/initramfs-pivot.md","filePath":"cs/initramfs-pivot.md","lastUpdated":1791413859000}'),f={name:"cs/initramfs-pivot.md"};function c(A,t,B,u,_,h){const e=p("Mermaid");return r(),E("div",null,[t[2]||(t[2]=s('<h1 id="initramfs-与-pivot-root" tabindex="-1">initramfs 与 pivot_root <a class="header-anchor" href="#initramfs-与-pivot-root" aria-label="Permalink to &quot;initramfs 与 pivot_root&quot;">​</a></h1><div class="epigraph"><p>initramfs 是内核解开的内存根：里面的脚本开 [dm-crypt](/cs/dm-crypt)、组 [RAID](/cs/md-raid)、加载驱动，再 pivot_root 到真正的磁盘根。</p><footer>—— 据 Linux initrd/initramfs 文档；pivot_root(2)；[tmpfs](/cs/tmpfs) 为内存树先修</footer></div><p><a href="/cs/tpm-measured-boot">TPM</a> 可能在这一阶段解封。<a href="/cs/device-nodes">设备节点</a> 需要驱动。缺口是 <strong>早期用户空间</strong> 与切换根，不是 systemd 全部。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>内核不能把所有磁盘/LVM/网络模块编进镜像。initramfs：cpio 进 RAM，<code>/init</code> 跑。缺口：<code>switch_root</code>/<code>pivot_root</code> 把旧根丢掉或移走，避免占用；与 <a href="/cs/overlayfs">overlay</a> 做运行时根。本课不把 dracut 模块列表抄完。</p><p><span class="marginnote">initrd 是旧块设备形式。今日多为 initramfs。紧急壳在此阶段常见。</span></p><p><span class="marginnote">术语翻译：initramfs 就是「放在内存里的临时根文件系统」——内核开机把它解包进 RAM，里面一个 /init 程序负责把真正的磁盘准备好。它解的是鸡生蛋问题：内核还没有能力挂磁盘根时，总得先有地方放驱动、解密脚本和 fsck 工具。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>内核挂载 ramfs → exec <code>/init</code> → 组装 <code>/dev</code>、解密、fsck → pivot 到 <code>/newroot</code>。对照 <a href="/cs/fuse">FUSE</a>：此时通常还没有。对照 <a href="/cs/nfs-semantics">NFS</a> 根：init 要先有网卡。对照 kexec：另一条启动，不在本课。</p>',9)),(r(),n(m,null,{default:o(()=>[l(e,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20K%5B%22%E5%86%85%E6%A0%B8%22%5D%20--%3E%20IR%5B%22initramfs%20%2Finit%22%5D%0A%20%20IR%20--%3E%20SETUP%5B%22%E9%A9%B1%E5%8A%A8%E4%B8%8E%E8%A7%A3%E5%AF%86%22%5D%0A%20%20SETUP%20--%3E%20PV%5B%22pivot_root%22%5D%0A%20%20PV%20--%3E%20REAL%5B%22%E7%A3%81%E7%9B%98%E4%B8%8A%E7%9A%84%20%2Fsbin%2Finit%22%5D%0A"})]),fallback:o(()=>[...t[0]||(t[0]=[a(" Loading... ",-1)])]),_:1})),t[3]||(t[3]=i("h2",{id:"机制",tabindex:"-1"},[a("机制 "),i("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),t[4]||(t[4]=i("p",null,[a("initramfs 把「内核太早、根还不可用」收成用户态程序，使复杂存储栈可启动。它是信任链的一环：未签名的 initramfs 可偷密钥。不要写成发行版安装器。与 "),i("a",{href:"/cs/memcg"},"memcg"),a("：此阶段通常无 cgroup 限制。")],-1)),t[5]||(t[5]=i("p",null,"失败：掉进 emergency shell，对象仍是这棵内存树。",-1)),t[6]||(t[6]=i("p",null,[a("实现上：initramfs 里的密钥提示是攻击面，TPM 解封应在此阶段。pivot 后要 umount 旧根，否则 ramfs 占着内存。emergency shell 仍是这棵树，网络可能还没有。 读法上只引用"),i("a",{href:"/cs/tpm-measured-boot"},"上一课"),a("的结论，不把对象换成训练推理或限价簿。")],-1)),t[7]||(t[7]=i("p",null,"pivot 前后旧根的去向：",-1)),(r(),n(m,null,{default:o(()=>[l(e,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20R1%5B%22%E8%BF%90%E8%A1%8C%E4%B8%AD%EF%BC%9A%E6%A0%B9%E6%98%AF%E5%86%85%E5%AD%98%E9%87%8C%E7%9A%84%20ramfs%22%5D%20--%3E%20P%5B%22pivot_root%20%E6%89%A7%E8%A1%8C%22%5D%0A%20%20P%20--%3E%20SW%5B%22%E6%97%A7%E6%A0%B9%E6%8C%AA%E5%88%B0%20%2Foldroot%EF%BC%8C%E7%A3%81%E7%9B%98%E6%A0%B9%E4%B8%8A%E4%BD%8D%22%5D%0A%20%20SW%20--%3E%20UM%5B%22umount%20%2Foldroot%22%5D%0A%20%20UM%20--%3E%20FREE%5B%22ramfs%20%E5%8D%A0%E7%9A%84%E5%86%85%E5%AD%98%E8%A2%AB%E9%87%8A%E6%94%BE%22%5D%0A%20%20UM%20--%20%22%E6%BC%8F%E4%BA%86%E8%BF%99%E4%B8%80%E6%AD%A5%22%20--%3E%20LEAK%5B%22%E4%B8%B4%E6%97%B6%E6%A0%B9%E4%B8%80%E7%9B%B4%E5%8D%A0%E7%9D%80%E5%86%85%E5%AD%98%E4%B8%8D%E6%94%BE%22%5D%0A"})]),fallback:o(()=>[...t[1]||(t[1]=[a(" Loading... ",-1)])]),_:1})),t[8]||(t[8]=s('<p><span class="marginnote">为什么重要：initramfs 是信任链的一环。磁盘解密口令往往就是在这里提示输入、在内存里解出来的——谁能改你的 initramfs，谁就能在这一刻把密钥抄走。所以签名校验要从这棵内存根开始，而不能只查磁盘上的系统。</span></p><p><span class="marginnote">常见误区：初学者掉进 emergency shell 会以为「系统坏了」。其实它是 initramfs 阶段的调试入口：此时你面对的仍是内存里那棵临时树，网络多半没起、磁盘可能还没解密——要修的是「通往真根的路」，而不是真根本身。</span></p><p>本课在操作系统进阶的「安全、启动与调试 / 内核安全与启动」课序里，对象是 <strong>initramfs 与 pivot_root</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有 resume from hibernate 细节——挂起后课。不保证嵌入式无 initramfs。下一课真正的 PID 1：systemd 单元。</p><p>版本字段会变，课序钉的是机制对象「initramfs 与 pivot_root」，不是某一主线内核的结构体名。 后课默认：磁盘根经 pivot 接上。systemd 单元与依赖，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>initramfs 在内存里准备真根。</li><li>pivot_root 切换，旧 ram 根释放。</li><li>systemd 单元是下一课。</li><li>出处：Linux initramfs；<code>pivot_root(2)</code>；dracut。</li></ul>',9))])}const P=d(f,[["render",c]]);export{D as __pageData,P as default};
